INSERT INTO "public"."Certification" ("id", "title", "issuer", "date", "description", "imageUrl", "credentialUrl", "createdAt", "updatedAt", "pdfUrl", "visible") VALUES ('cmadsdssm0000jyrs00s004db', 'Programming using Java', 'Infosys | Springboard', '2025-03-31 00:00:00', 'The course provided me with an introduction to the fundamentals of object-oriented programming and Java as the programming language.', 'https://i.vgy.me/Y0FCKU.png', null, '2025-05-07 10:19:26.832', '2025-05-15 10:11:35.107', 'https://drive.google.com/file/d/1XiVj-__E7BNtLoVwzLjgbfIIbzvAw-6D/view', 'public'), ('cmadt5v8d0000fq3xj883bo7i', 'Basics of Python', 'Infosys | Springboard', '2024-07-30 00:00:00', 'This course provided me with an understanding of the fundamental concepts of Python, which are the basis of this programming language.', 'https://i.vgy.me/NwpUHE.png', 'https://verify.onwingspan.com/', '2025-05-07 10:41:16.381', '2025-05-07 10:42:20.691', 'https://drive.google.com/file/d/1XiVj-__E7BNtLoVwzLjgbfIIbzvAw-6D/view', 'public'), ('cmap8kn5c0000e2kfsgz8ow6i', 'Inspire 2k25 C-Evolution', 'C.K Pithawalla College of Engineering & Technology', '2025-03-07 00:00:00', 'Participation in C Quiz', 'https://ik.imagekit.io/i6dlpbs14/certifications/Acrobat_ed5rqJ2xka_Tdb06aTDk.png', null, '2025-05-15 10:38:07.724', '2025-05-15 10:56:17.177', 'https://drive.google.com/file/d/14VgxXaKuda-e4tVDSHzs7dCfdBYfHzqQ/view', 'public'), ('cmap8ozgg0001e2kfd93n03wt', 'Internship in Web development with React', 'Sridix Technology', '2023-06-09 00:00:00', 'Developed three websites. Two of which utilize the browser''s local storage as a database. while the final one is a fully developed project that utilizes Supabase Postgres as its database.', 'https://ik.imagekit.io/i6dlpbs14/certifications/Acrobat_xqsDa3NROJ_ttQqfqe-u.png', null, '2025-05-15 10:41:30.474', '2025-05-15 10:41:30.474', 'https://drive.google.com/file/d/1QwSalh7e1PLsdqznDqb3-UKnAbGFve0V/view', 'public'), ('cmap8szae0002e2kfok2r24ru', 'Best Solution to Impact Academia', 'Indian Society of Technical Education, Gujarat Section (ISTE)', '2023-03-25 00:00:00', 'We won an award for Best Solution to impact Acedemia. a state-level programming competition organized by the Indian Society for Technical Education (STE), Gujarat Section, and B&B Institute of Technology, Vallabh Vidyanagar.', 'https://ik.imagekit.io/i6dlpbs14/certifications/Acrobat_uNWJadRgdI_bXXIH9MDx.png', null, '2025-05-15 10:44:36.878', '2025-05-15 10:44:36.878', 'https://drive.google.com/file/d/1Y0QwZmUiTi2U4bGc2m3iTefMieNzvrvI/view', 'public'), ('cmap8vn1o0003e2kfdj3rb7d6', 'Pythakon - 2k22', 'CHARUSAT campus', '2022-08-06 00:00:00', 'Participation in the national level hackathon Pythakon-2k22
